'use strict';

const $ = (id) => document.getElementById(id);
const form = $('context-form');
let context = null;
let sample = false;
let busy = false;
let timer = null;
const REQUEST_TIMEOUT = 180_000; // Clone (60s) + Gemini (90s), with response overhead.

function icon(name) {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  const use = document.createElementNS('http://www.w3.org/2000/svg', 'use');
  use.setAttribute('href', `#i-${name}`);
  svg.append(use);
  return svg;
}

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function sourceTags(files) {
  const tags = el('div', 'source-tags');
  for (const file of files) tags.append(el('span', '', file));
  return tags;
}

function validateContext(value, sessionId) {
  const strings = (items) => Array.isArray(items) && items.every((item) => typeof item === 'string');
  const sourced = (item) => item && strings(item.source_files);
  if (!value || value.session_id !== sessionId || typeof value.summary !== 'string' ||
      typeof value.role !== 'string' || typeof value.repo_url !== 'string' ||
      !strings(value.included_files) || !strings(value.omitted_files) ||
      !Array.isArray(value.technologies) || !value.technologies.every((t) => sourced(t) && typeof t.name === 'string' && typeof t.usage === 'string') ||
      !Array.isArray(value.project_areas) || !value.project_areas.every((a) => sourced(a) && typeof a.name === 'string' && typeof a.description === 'string' && strings(a.optimization_topics)) ||
      !Array.isArray(value.questions) || value.questions.length !== 3 || !value.questions.every((q) => sourced(q) && ['question', 'answer', 'context'].every((key) => typeof q[key] === 'string'))) {
    throw new Error('The server returned incomplete context. Please generate a new analysis.');
  }
  return value;
}

async function request(url, options = {}) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    let data;
    try { data = await response.json(); }
    catch { throw new Error(`The server returned an unreadable response (${response.status}). Check the server and try again.`); }
    if (!response.ok) {
      const detail = typeof data.detail === 'string' ? data.detail : `Request failed (${response.status}). Check the repository URL and try again.`;
      throw new Error(detail);
    }
    return data;
  } catch (error) {
    if (error.name === 'AbortError') throw new Error('The request timed out. Analysis may still finish on the server; check server logs before trying again.');
    if (error instanceof TypeError) throw new Error('Could not reach the server. Check your connection and try again.');
    throw error;
  } finally { clearTimeout(timeout); }
}

function setAgent(state, title, description, status) {
  $('agent-panel').className = `panel agent-panel ${state}`;
  $('agent-title').textContent = title;
  $('agent-description').textContent = description;
  $('agent-state').replaceChildren(el('span', 'status-dot'), document.createTextNode(state === 'running' ? 'Agent working' : state === 'complete' ? 'Context ready' : state === 'failed' ? 'Needs attention' : 'Ready when you are'));
  $('agent-status-text').textContent = status;
}

function setBusy(value) {
  busy = value;
  for (const field of form.elements) field.disabled = value;
  $('preview-button').disabled = value;
  $('example-button').disabled = value;
  $('agent-panel').setAttribute('aria-busy', String(value));
  $('analyze-button').querySelector('span').textContent = value ? 'Generating context…' : 'Generate context';
  clearInterval(timer);
  $('elapsed').textContent = '';
  if (value) {
    const started = Date.now();
    timer = setInterval(() => { $('elapsed').textContent = `${Math.floor((Date.now() - started) / 1000)}s`; }, 1000);
  }
}

function showError(error) {
  $('form-error').textContent = error.message;
  $('form-error').hidden = false;
  setAgent('failed', 'Let’s reconnect.', 'We couldn’t complete this request. Your repository settings are still here.', 'Analysis unsuccessful. Review the message beside the form.');
}

function selectTab(name, focus = false) {
  for (const tab of document.querySelectorAll('[role="tab"]')) {
    const selected = tab.dataset.tab === name;
    tab.setAttribute('aria-selected', String(selected));
    tab.tabIndex = selected ? 0 : -1;
    $(`view-${tab.dataset.tab}`).hidden = !selected;
    if (selected && focus) tab.focus();
  }
}

function render(data, isSample = false) {
  context = data;
  sample = isSample;
  $('empty-output').hidden = true;
  $('results').hidden = false;
  $('results').classList.remove('animate-in');
  requestAnimationFrame(() => $('results').classList.add('animate-in'));
  $('output-actions').hidden = false;
  $('copy-button').hidden = isSample;
  $('output-badge').textContent = isSample ? 'SAMPLE PREVIEW' : 'CONTEXT READY';
  $('output-subtitle').textContent = isSample ? 'Illustrative FlatPal context. This preview does not run the agent or create a session.' : 'Source-grounded context, saved and ready for your agents.';
  $('result-repository').textContent = data.repo_url.replace('https://github.com/', '') + (data.subdir ? ` / ${data.subdir}` : '');
  $('result-role').textContent = data.role;
  $('result-summary').textContent = data.summary;
  $('stat-files').textContent = String(data.included_files.length).padStart(2, '0');
  $('stat-tech').textContent = String(data.technologies.length).padStart(2, '0');
  $('technology-list').replaceChildren(...data.technologies.map((tech) => {
    const card = el('article', 'technology-card');
    card.append(el('h4', '', tech.name), el('p', '', tech.usage), sourceTags(tech.source_files));
    return card;
  }));
  $('area-list').replaceChildren(...data.project_areas.map((area) => {
    const card = el('article', 'area-card');
    const topics = el('ul', 'topic-list');
    topics.append(...area.optimization_topics.map((topic) => el('li', '', topic)));
    card.append(el('h4', '', area.name), el('p', '', area.description), topics, sourceTags(area.source_files));
    return card;
  }));
  $('question-list').replaceChildren(...data.questions.map((question, index) => {
    const card = el('article', 'question-card');
    const title = el('div', 'question-title');
    title.append(el('span', 'question-number', `0${index + 1}`), el('h3', '', question.question));
    card.append(title);
    for (const [label, text] of [['Reference answer', question.answer], ['Codebase context', question.context]]) {
      const details = el('details');
      const content = el('div', 'question-detail');
      content.append(el('p', '', text));
      if (label === 'Codebase context') content.append(sourceTags(question.source_files));
      details.append(el('summary', '', label), content);
      card.append(details);
    }
    return card;
  }));
  $('included-list').replaceChildren(...data.included_files.map((file) => el('li', '', file)));
  $('omitted-list').replaceChildren(...(data.omitted_files.length ? data.omitted_files.map((file) => el('li', '', file)) : [el('li', '', 'No budget omissions were reported.')]));
  $('interview-link').hidden = isSample;
  if (!isSample) $('interview-link').href = `/?session=${encodeURIComponent(data.session_id)}`;
  $('handoff-note').replaceChildren();
  if (isSample) $('handoff-note').textContent = 'Generate real context from a public repository to create an interview session.';
  else $('handoff-note').append(document.createTextNode('Before starting, add the candidate profile to '), el('code', '', `data/${data.session_id}/candidate.md`), document.createTextNode('.'));
  selectTab('context');
  setAgent('complete', isSample ? 'A glimpse of the signal.' : 'Your code. Understood.', isSample ? 'Explore the kind of context your agents can share. Generate an analysis for actual repository results.' : `${data.technologies.length} technologies. ${data.project_areas.length} project areas. Three questions grounded in your code.`, isSample ? 'Sample preview · no agent run or session created.' : `Analysis saved · ${data.included_files.length} source files included.`);
}

function remember(key, value) {
  const url = new URL(location.href);
  url.searchParams.delete('context');
  url.searchParams.delete('sample');
  url.searchParams.set(key, value);
  history.replaceState(null, '', url);
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (busy) return;
  $('form-error').hidden = true;
  const repo_url = $('repo-url').value.trim();
  const role = $('role').value.trim();
  const subdir = $('subdir').value.trim();
  if (!/^https:\/\/github\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/?$/.test(repo_url)) {
